// decodeAdminUser pulls an adminUser out of a 2xx response.
func decodeAdminUser(t *testing.T, resp *http.Response) adminUser {
	t.Helper()
	var au adminUser
	if err := json.NewDecoder(resp.Body).Decode(&au); err != nil {
		t.Fatalf("decode adminUser: %v", err)
	}
	return au
}

// userPath renders a user id into its admin route path.
func userPath(id int64) string {
	return "/api/v1/admin/users/" + strconv.FormatInt(id, 10)
}

// countRows is the raw store read the cascade assertions use (the test
// grounds the delete cascade in the TABLES, not in another identity read).
func countRows(t *testing.T, st *store.Store, q string, args ...any) int {
	t.Helper()
	var n int
	if err := st.DB().QueryRowContext(context.Background(), q, args...).Scan(&n); err != nil {
		t.Fatalf("count %q: %v", q, err)
	}
	return n
}

// TestAdminUsersEndpoints pins the users admin surface end to end over the
// REAL router (l6-accounts 9.1): the first-user one-way-door notice (first
// create only), the duplicate-username 409, the hashless list wire, the
// role/disable patch with the 7.1 projection and the fail-closed disable,
// the password reset's session cascade, and the delete's last-user guard +
// state cascade. Every request rides the same chain production rides
// (authMiddleware → requireRole(RoleAdmin) → handler).
func TestAdminUsersEndpoints(t *testing.T) {
	ctx := context.Background()

	t.Run("create_first_user_carries_notice", func(t *testing.T) {
		// A FRESH deployment so the first create's body is still unread:
		// its raw wire is the notice assertion target.
		empty := openAPIStore(t)
		fresh := authChainRouter(t, empty, identity.NewService(empty, nil))
		first := doRequest(t, fresh, http.MethodPost, "/api/v1/admin/users",
			`{"username":"Anna","password":"pw"}`, adminToken)
		defer first.Body.Close()
		if first.StatusCode != http.StatusCreated {
			t.Fatalf("first create = %d, want 201", first.StatusCode)
		}
		var wire map[string]any
		if err := json.NewDecoder(first.Body).Decode(&wire); err != nil {
			t.Fatalf("decode first-create wire: %v", err)
		}
		if id, ok := wire["id"].(float64); !ok || id <= 0 {
			t.Fatalf("first create wire = %v, want a real user row", wire)
		}
		if got := wire["username"]; got != "anna" {
			t.Fatalf("first create username = %v, want lowercase-normalized anna", got)
		}
		notice, ok := wire["notice"].(string)
		if !ok || notice != firstUserNotice {
			t.Fatalf("first create notice = %q (present %v), want %q", notice, ok, firstUserNotice)
		}

		// The SECOND create on a now-populated store carries NO notice — the
		// door swung once (spec: "a second creation carries no such notice").
		second := doRequest(t, fresh, http.MethodPost, "/api/v1/admin/users",
			`{"username":"spare","password":"pw"}`, adminToken)
		defer second.Body.Close()
		if second.StatusCode != http.StatusCreated {
			t.Fatalf("second create = %d, want 201", second.StatusCode)
		}
		var wire2 map[string]any
		if err := json.NewDecoder(second.Body).Decode(&wire2); err != nil {
			t.Fatalf("decode second-create wire: %v", err)
		}
		if _, ok := wire2["notice"]; ok {
			t.Fatalf("second create carries a notice: %v", wire2)
		}
	})

	t.Run("create_refusals", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		h := authChainRouter(t, st, ident)
		if _, err := ident.Create(ctx, "alia", "pw"); err != nil {
			t.Fatalf("identity.Create: %v", err)
		}

		// Duplicate username — normalization collides the mixed case onto the
		// UNIQUE row: 409 conflict.
		dup := doRequest(t, h, http.MethodPost, "/api/v1/admin/users",
			`{"username":"ALIA","password":"pw"}`, adminToken)
		defer dup.Body.Close()
		if dup.StatusCode != http.StatusConflict {
			t.Fatalf("duplicate create = %d, want 409", dup.StatusCode)
		}
		if eb := decodeError(t, dup); eb.Error.Code != "conflict" {
			t.Fatalf("duplicate error code = %q, want conflict", eb.Error.Code)
		}

		// Validation-first 400s: malformed JSON, empty username, empty
		// password — nothing written on any of them.
		for _, bad := range []string{
			`{"username":`,
			`{"username":"  ","password":"pw"}`,
			`{"username":"x","password":""}`,
		} {
			resp := doRequest(t, h, http.MethodPost, "/api/v1/admin/users", bad, adminToken)
			code := resp.StatusCode
			resp.Body.Close()
			if code != http.StatusBadRequest {
				t.Fatalf("create body %q = %d, want 400", bad, code)
			}
		}
	})

	t.Run("list_serves_no_hashes", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		h := authChainRouter(t, st, ident)

		// The empty store serves the [] literal, never null.
		empty := doRequest(t, h, http.MethodGet, "/api/v1/admin/users", "", adminToken)
		var rawEmpty map[string]json.RawMessage
		if err := json.NewDecoder(empty.Body).Decode(&rawEmpty); err != nil {
			t.Fatalf("decode empty list: %v", err)
		}
		empty.Body.Close()
		if string(rawEmpty["users"]) != "[]" {
			t.Fatalf("empty users = %s, want []", rawEmpty["users"])
		}

		if _, err := ident.Create(ctx, "kai", "pw"); err != nil {
			t.Fatalf("identity.Create kai: %v", err)
		}
		if _, err := ident.Create(ctx, "noor", "pw"); err != nil {
			t.Fatalf("identity.Create noor: %v", err)
		}
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/users", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("list = %d, want 200", resp.StatusCode)
		}
		var lr adminUsersResponse
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode adminUsersResponse: %v", err)
		}
		if len(lr.Users) != 2 {
			t.Fatalf("listed users = %d, want 2", len(lr.Users))
		}
		// The RAW wire never carries hash material or the prefs document (the
		// served-fields law — hashes never leave the domain; the profile is
		// prefs' surface).
		raw, err := json.Marshal(lr)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		for _, forbidden := range []string{"password_hash", "PasswordHash", "prefs", "argon2id"} {
			if strings.Contains(string(raw), forbidden) {
				t.Fatalf("user list wire carries %q: %s", forbidden, raw)
			}
		}
	})

	t.Run("patch_role_projects_and_disable_fails_closed", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		u, err := ident.Create(ctx, "rhea", "pw")
		if err != nil {
			t.Fatalf("identity.Create: %v", err)
		}
		sess, err := ident.MintSession(ctx, "rhea", "pw")
		if err != nil {
			t.Fatalf("MintSession: %v", err)
		}
		h := authChainRouter(t, st, ident)
		path := userPath(u.ID)

		// Role patch → the SAME live session reaches the admin group on the
		// next verify (D11 projection, end to end through the middleware).
		patch := doRequest(t, h, http.MethodPatch, path, `{"role":"admin"}`, adminToken)
		defer patch.Body.Close()
		if patch.StatusCode != http.StatusOK {
			t.Fatalf("role patch = %d, want 200", patch.StatusCode)
		}
		if au := decodeAdminUser(t, patch); au.Role != "admin" || au.Disabled {
			t.Fatalf("patched row = %+v, want {admin, false}", au)
		}
		projected := doRequest(t, h, http.MethodGet, "/api/v1/admin/users", "", sess.Token)
		projected.Body.Close()
		if projected.StatusCode != http.StatusOK {
			t.Fatalf("admin-role session on admin route = %d, want 200 (role projection)", projected.StatusCode)
		}

		// Disable patch → the same live token 401s (fail closed, the disabled
		// gate re-checked at every verify).
		patch2 := doRequest(t, h, http.MethodPatch, path, `{"disabled":true}`, adminToken)
		defer patch2.Body.Close()
		if patch2.StatusCode != http.StatusOK {
			t.Fatalf("disable patch = %d, want 200", patch2.StatusCode)
		}
		if au := decodeAdminUser(t, patch2); !au.Disabled || au.Role != "admin" {
			t.Fatalf("patched row = %+v, want {admin, true} (partial — role untouched)", au)
		}
		blocked := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", sess.Token)
		blocked.Body.Close()
		if blocked.StatusCode != http.StatusUnauthorized {
			t.Fatalf("disabled user's live session = %d, want 401", blocked.StatusCode)
		}

		// Refusals: unknown id 404, unknown role 400, empty patch body 400,
		// non-integer id 400.
		for _, tc := range []struct {
			method, path, body string
			code               int
		}{
			{http.MethodPatch, userPath(999), `{"role":"user"}`, http.StatusNotFound},
			{http.MethodPatch, path, `{"role":"root"}`, http.StatusBadRequest},
			{http.MethodPatch, path, `{}`, http.StatusBadRequest},
			{http.MethodPatch, "/api/v1/admin/users/abc", `{"role":"user"}`, http.StatusBadRequest},
		} {
			resp := doRequest(t, h, tc.method, tc.path, tc.body, adminToken)
			code := resp.StatusCode
			resp.Body.Close()
			if code != tc.code {
				t.Fatalf("%s %s %s = %d, want %d", tc.method, tc.path, tc.body, code, tc.code)
			}
		}
	})

	t.Run("password_reset_cascades_sessions", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		u, err := ident.Create(ctx, "talia", "pw")
		if err != nil {
			t.Fatalf("identity.Create: %v", err)
		}
		sess, err := ident.MintSession(ctx, "talia", "pw")
		if err != nil {
			t.Fatalf("MintSession: %v", err)
		}
		h := authChainRouter(t, st, ident)
		path := userPath(u.ID) + "/password"

		reset := doRequest(t, h, http.MethodPut, path, `{"password":"new-pw"}`, adminToken)
		defer reset.Body.Close()
		if reset.StatusCode != http.StatusNoContent {
			t.Fatalf("reset = %d, want 204", reset.StatusCode)
		}

		// The pre-reset session is dead (the D6 cascade — re-use fails closed).
		old := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", sess.Token)
		old.Body.Close()
		if old.StatusCode != http.StatusUnauthorized {
			t.Fatalf("pre-reset session after reset = %d, want 401", old.StatusCode)
		}
		// The old password no longer mints; the new one does.
		if _, err := ident.MintSession(ctx, "talia", "pw"); err == nil {
			t.Fatalf("old password still mints after reset")
		}
		if _, err := ident.MintSession(ctx, "talia", "new-pw"); err != nil {
			t.Fatalf("MintSession new pw: %v", err)
		}

		// Refusals: unknown id 404, empty password 400.
		for _, tc := range []struct {
			path, body string
			code       int
		}{
			{userPath(999) + "/password", `{"password":"x"}`, http.StatusNotFound},
			{path, `{"password":""}`, http.StatusBadRequest},
		} {
			resp := doRequest(t, h, http.MethodPut, tc.path, tc.body, adminToken)
			code := resp.StatusCode
			resp.Body.Close()
			if code != tc.code {
				t.Fatalf("PUT %s %s = %d, want %d", tc.path, tc.body, code, tc.code)
			}
		}
	})

	t.Run("delete_guards_last_and_cascades_state", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		h := authChainRouter(t, st, ident)
		mk := func(name string) identity.User {
			u, err := ident.Create(ctx, name, "pw")
			if err != nil {
				t.Fatalf("identity.Create %s: %v", name, err)
			}
			return u
		}
		// alpha is deleted via identity below (seeding the guard setup);
		// b is the sole survivor the endpoint must refuse to delete.
		_, b, c := mk("alpha"), mk("beta"), mk("gamma")

		// Seed the doomed user's live state: a session, both ledger slots
		// (stamped into c's slot via the REAL store writes), and group
		// membership — exactly what the one-tx cascade must take.
		sess, err := ident.MintSession(ctx, "gamma", "pw")
		if err != nil {
			t.Fatalf("MintSession: %v", err)
		}
		// The ledger writes are viewer-scoped (the item must exist AND be in
		// the viewer's visible set — hidden ≡ unknown), so seed a real library
		// + item row and grant c exactly that library.
		lib := seedLibrary(t, st, "/media/cascade")
		seed := store.Item{
			ID: "itm-c-1", ModuleID: "tv", LibraryID: lib, FileID: "fid-c-1",
			RelativePath: "Cascade S01E01.mkv", MediaType: "tv",
			Document:      json.RawMessage(`{}`),
			SchemaVersion: 1,
		}
		if err := st.PutItem(ctx, seed); err != nil {
			t.Fatalf("PutItem: %v", err)
		}
		cViewer := access.User(c.ID, []int64{lib}, nil)
		if _, err := st.PutProgress(ctx, seed.ID, 42, cViewer); err != nil {
			t.Fatalf("PutProgress: %v", err)
		}
		if err := st.InsertWatched(ctx, "itm-c-2", lib, "", time.Now().UTC(), cViewer); err != nil {
			t.Fatalf("InsertWatched: %v", err)
		}
		if _, err := ident.CreateGroup(ctx, "Scope"); err != nil {
			t.Fatalf("CreateGroup: %v", err)
		}
		if err := ident.AddUser(ctx, "Scope", "gamma"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}

		// A non-last delete goes through: 204, and the cascade takes the
		// user's state — sessions die (re-use 401s), both ledger slots and
		// membership are gone, asserted against the RAW tables.
		del := doRequest(t, h, http.MethodDelete, userPath(c.ID), "", adminToken)
		defer del.Body.Close()
		if del.StatusCode != http.StatusNoContent {
			t.Fatalf("non-last delete = %d, want 204", del.StatusCode)
		}
		old := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", sess.Token)
		old.Body.Close()
		if old.StatusCode != http.StatusUnauthorized {
			t.Fatalf("deleted user's session = %d, want 401", old.StatusCode)
		}
		if n := countRows(t, st, `SELECT COUNT(*) FROM playback_progress WHERE user_id = ?`, c.ID); n != 0 {
			t.Fatalf("playback_progress rows survived the cascade: %d", n)
		}
		if n := countRows(t, st, `SELECT COUNT(*) FROM watched_items WHERE user_id = ?`, c.ID); n != 0 {
			t.Fatalf("watched_items rows survived the cascade: %d", n)
		}
		if n := countRows(t, st, `SELECT COUNT(*) FROM group_members WHERE user_id = ?`, c.ID); n != 0 {
			t.Fatalf("group_members rows survived the cascade: %d", n)
		}

		// Down to the sole user: the guard refuses with the canonical 409 and
		// the user survives.
		if err := ident.DeleteUser(ctx, "alpha"); err != nil {
			t.Fatalf("identity.DeleteUser alpha: %v", err)
		}
		last := doRequest(t, h, http.MethodDelete, userPath(b.ID), "", adminToken)
		defer last.Body.Close()
		if last.StatusCode != http.StatusConflict {
			t.Fatalf("last-user delete = %d, want 409", last.StatusCode)
		}
		if eb := decodeError(t, last); eb.Error.Code != "conflict" {
			t.Fatalf("last-user error code = %q, want conflict", eb.Error.Code)
		}
		if _, err := ident.UserByID(ctx, b.ID); err != nil {
			t.Fatalf("last user did not survive the refused delete: %v", err)
		}

		// Unknown id → 404 everywhere.
		for _, rr := range []struct {
			method, path string
		}{
			{http.MethodPatch, userPath(424242)},
			{http.MethodPut, userPath(424242) + "/password"},
			{http.MethodDelete, userPath(424242)},
		} {
			body := `{"role":"user"}`
			if rr.method == http.MethodPut {
				body = `{"password":"x"}`
			}
			resp := doRequest(t, h, rr.method, rr.path, body, adminToken)
			code := resp.StatusCode
			resp.Body.Close()
			if code != http.StatusNotFound {
				t.Fatalf("%s %s = %d, want 404", rr.method, rr.path, code)
			}
		}
	})
}
